// page's to every component.
import type { ShiftKind, Words } from '../mock-data';

export type Lang = 'en' | 'ar';

/** Arabic when the browser's first language is, else English. */
export const langOf = (language: string | undefined): Lang => ((language ?? '').trim().toLowerCase().startsWith('ar') ? 'ar' : 'en');

