/** How the page's language writes numbers, days and times: Arabic-Indic digits in Arabic, as the words above. */
export function formats(lang: Lang) {
  const intl = lang === 'ar' ? 'ar-u-nu-arab' : 'en-GB';
  const number = (n: number): string => new Intl.NumberFormat(intl).format(n);
  return {
    number,
    /** A day, such as "Saturday 7 November". */
    day: (date: Date): string => new Intl.DateTimeFormat(intl, { weekday: 'long', day: 'numeric', month: 'long' }).format(date),
    /** A time of day, such as "09:00". */
    time: (date: Date): string => new Intl.DateTimeFormat(intl, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(date),
    /** A text from the data, in the page's language. */
    words: (w: Words): string => w[lang],
  };
}
